import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

const require = createRequire(import.meta.url);

type PackageJson = {
  name: string;
  version: string;
  bin?: string | Record<string, string>;
};

function findPackageJson(entryPath: string): string {
  let currentDir = path.dirname(entryPath);
  while (currentDir !== path.dirname(currentDir)) {
    const packageJsonPath = path.join(currentDir, 'package.json');
    try {
      readFileSync(packageJsonPath);
      return packageJsonPath;
    } catch {
      currentDir = path.dirname(currentDir);
    }
  }
  throw new Error(`unable to find package.json for ${entryPath}`);
}

export function resolveBin(
  moduleName: string,
  {
    executable = moduleName,
    paths = [process.cwd()],
  }: { executable?: string; paths?: string[] } = {}
): string {
  let packageJsonPath: string;
  try {
    packageJsonPath = require.resolve(`${moduleName}/package.json`, { paths });
  } catch {
    packageJsonPath = findPackageJson(require.resolve(moduleName, { paths }));
  }

  const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf8')) as PackageJson;
  if (!packageJson.bin) {
    throw new Error(
      `no bin found in ${packageJson.name}@${packageJson.version} in path ${packageJsonPath}`
    );
  }

  const binRelativePath =
    typeof packageJson.bin === 'string'
      ? packageJson.bin
      : packageJson.bin[executable];
  if (!binRelativePath) {
    throw new Error(
      `no "${executable}" executable found in ${packageJson.name}@${packageJson.version}`
    );
  }
  return path.resolve(path.dirname(packageJsonPath), binRelativePath);
}

/**
 * Resolve the native tsgolint executable (`@oxlint-tsgolint/<platform>-<arch>`),
 * not the `oxlint-tsgolint` JS launcher (`bin/tsgolint.js`).
 *
 * oxlint spawns the path given via OXLINT_TSGOLINT_PATH directly as a native
 * process. On Windows a `.js` launcher cannot be executed that way and fails with
 * "%1 is not a valid Win32 application. (OS error 193)". Pointing oxlint at the
 * platform-specific binary works on every OS.
 */
export function resolveTsgolintBin(paths: string[] = [process.cwd()]): string {
  const platformPkg = `@oxlint-tsgolint/${process.platform}-${process.arch}`;
  const exeName = process.platform === 'win32' ? 'tsgolint.exe' : 'tsgolint';
  // Resolve from the oxlint-tsgolint package location so the optional platform
  // dependency is found in the same node_modules tree (e.g. inside capsules).
  let resolveFromPaths = paths;
  try {
    const launcherPkg = require.resolve('oxlint-tsgolint/package.json', { paths });
    resolveFromPaths = [path.dirname(launcherPkg), ...paths];
  } catch {
    // fall back to the provided paths
  }
  return require.resolve(`${platformPkg}/${exeName}`, {
    paths: resolveFromPaths,
  });
}
